{"Intent":"Fix First panicking when n is negative or larger than the list.","Target":"f491dc99b8f4b4887d0b2613ca4466523807d9c5","Head":"b6fb81e3a1685b55e45cbba2946e7a8fe854938a","Diff":"diff --git a/list/first.go b/list/first.go
index 264ce61..fbf7ca6 100644
--- a/list/first.go
+++ b/list/first.go
@@ -2,5 +2,11 @@ package list

 // First returns up to n leading items.
 func First(items []string, n int) []string {
+	if n < 0 {
+		n = 0
+	}
+	if n > len(items) {
+		n = len(items)
+	}
 	return items[:n]
 }
